local PRELOAD_ORDER = {"open", "focus", "hover", "click", "enter", "warn", "error", "success", "close", "copy", "drag", "launch"}

local B64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64_LOOKUP = {}
for i = 1, 64 do B64_LOOKUP[B64_CHARS:sub(i, i)] = i - 1 end

local function b64decode(data)
    data = data:gsub("[^%w%+/=]", "")
    local out, n = {}, 0
    for i = 1, #data, 4 do
        local c1, c2, c3, c4 = data:sub(i, i), data:sub(i + 1, i + 1), data:sub(i + 2, i + 2), data:sub(i + 3, i + 3)
        local a, b = B64_LOOKUP[c1], B64_LOOKUP[c2]
        local c, d = B64_LOOKUP[c3], B64_LOOKUP[c4]
        if not (a and b) then break end
        local v = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
        n = n + 1
        if c3 == "=" or not c then
            out[n] = string.char(math.floor(v / 65536))
        elseif c4 == "=" or not d then
            out[n] = string.char(math.floor(v / 65536), math.floor(v / 256) % 256)
        else
            out[n] = string.char(math.floor(v / 65536), math.floor(v / 256) % 256, v % 256)
        end
    end
    return table.concat(out)
end

local soundAssets = {}
local soundLoading = {}
local function loadSoundAsset(key)
    if soundAssets[key] ~= nil then return soundAssets[key] or nil end
    -- another thread is already decoding this one: wait for it instead of writing the file twice
    if soundLoading[key] then
        while soundLoading[key] do task.wait() end
        return soundAssets[key] or nil
    end
    soundLoading[key] = true
    local asset = nil
    pcall(function()
        local getAsset = getcustomasset or getsynasset
        local info = SOUND_DATA[key]
        if not (getAsset and writefile and readfile and isfile and info) then return end
        local path = "Exotica_" .. key .. ".mp3"
        local okSize = false
        if isfile(path) then
            local existing = readfile(path)
            okSize = existing ~= nil and #existing == info.size
        end
        if not okSize then
            writefile(path, b64decode(info.data))
        end
        asset = getAsset(path)
    end)
    soundAssets[key] = asset or false
    soundLoading[key] = nil
    return asset
end

local function playSound(id, volume, speed)
    pcall(function()
        local s = Instance.new("Sound")
        s.SoundId = id
        s.Volume = volume or 0.6
        s.PlaybackSpeed = speed or 1
        s.Parent = SoundService
        s.Ended:Once(function() s:Destroy() end)
        s:Play()
        task.delay(10, function() if s.Parent then s:Destroy() end end)
    end)
end

-- only these fall back to the built-in ping if custom assets are unavailable;
-- the rest (hover, focus, drag...) stay silent so the fallback never spams
local FALLBACK_KEYS = { enter = true, success = true, error = true }

-- default volume / pitch per sound (the mp3s are all peak-normalised, so this is the mix)
local SOUND_MIX = {
    open    = { 0.45, 1.0 },
    focus   = { 0.35, 1.0 },
    hover   = { 0.22, 1.0 },
    click   = { 0.55, 1.0 },
    enter   = { 0.60, 1.0 },
    warn    = { 0.45, 1.0 },
    error   = { 0.60, 1.0 },
    success = { 0.65, 1.0 },
    close   = { 0.45, 1.0 },
    copy    = { 0.50, 1.0 },
    drag    = { 0.20, 1.0 },
    launch  = { 0.50, 1.0 },
}

-- plays one of the embedded sounds (loads it first if this is the first time)
-- usage: playEmbedded("hover") or playEmbedded("click", 0.4, 1.1)
local function playEmbedded(key, volume, speed)
    task.spawn(function()
        local mix = SOUND_MIX[key] or { 0.6, 1 }
        local asset = loadSoundAsset(key)
        if not asset and not FALLBACK_KEYS[key] then return end
        playSound(asset or FALLBACK_SOUND, volume or mix[1], speed or mix[2])
    end)
end

-- decode + write every sound in the background so nothing hitches on first use
task.spawn(function()
    for _, key in ipairs(PRELOAD_ORDER) do
        loadSoundAsset(key)
        task.wait()
    end
end)

print("--- LOADER STARTED ---")

----------------------------------------------------------------
-- AUTH (unchanged)
----------------------------------------------------------------
local function safeRequest(requestData)
    local reqFunc = request or (syn and syn.request) or (http and http.request)
    if not reqFunc then return nil end
    local success, res = pcall(function() return reqFunc(requestData) end)
    if not success then return nil end
    return res
end

local function urlEncode(s)
    return (tostring(s):gsub("[^%w%-_%.~]", function(c)
        return string.format("%%%02X", string.byte(c))
    end))
end

-- Stable per-machine ID. Must NOT contain anything that changes between sessions
-- (JobId changes every server, which caused the "hardware mismatch" on rejoin).
local function getHWID()
    local ok, id = pcall(function()
        return game:GetService("RbxAnalyticsService"):GetClientId()
    end)
    if ok and type(id) == "string" and id ~= "" then
        return id
    end
    if gethwid then
        local ok2, id2 = pcall(gethwid)
        if ok2 and type(id2) == "string" and id2 ~= "" then return id2 end
    end
    return "uid_" .. tostring(player.UserId)
end

local function initKeyAuth()
    local initUrl = string.format("https://keyauth.win/api/1.2/?type=init&name=%s&ownerid=%s&ver=%s",
        urlEncode(name), urlEncode(ownerid), urlEncode(version))
    local response = safeRequest({ Url = initUrl, Method = "GET" })
    if response and response.StatusCode == 200 then
        local successDec, data = pcall(function() return HttpService:JSONDecode(response.Body) end)
        if successDec and data and data.success then
            sessionid = data.sessionid
            return true
        end
    end
    return false
end

local function executeMasterScript(keyUsed, hwidUsed)
    playEmbedded("launch")

    local workerUrl = string.format(
        "https://tight-voice-4d4b.wmarshall689.workers.dev/?key=%s&hwid=%s",
        urlEncode(keyUsed or ""), urlEncode(hwidUsed or ""))

    local fetchSuccess, result = pcall(function() return game:HttpGet(workerUrl) end)
    if not fetchSuccess or not result or result == ""
        or result:match("^Invalid key") or result:match("^Auth init failed")
        or result:match("^Script") or result:match("^Missing") then
        return
    end

    -- Sets the global session token so the master script knows it came through the loader!
    _G.ExoticaAuthorizedSession = true

    local fn, err = loadstring(result)
    if not fn then return end
    pcall(fn)
end

-- Only these server messages mean the saved key is permanently unusable.
-- Anything else (network failure, init failure, session errors) keeps the saved key.
local function isFatalKeyMessage(msg)
    msg = tostring(msg or ""):lower()
    return msg:find("expired", 1, true)
        or msg:find("not found", 1, true)
        or msg:find("invalid key", 1, true)
        or msg:find("banned", 1, true)
        or msg:find("blacklist", 1, true)
        or msg:find("already used", 1, true)
        or msg:find("hwid", 1, true) and msg:find("mismatch", 1, true)
        or msg:find("hwid", 1, true) and msg:find("doesn't match", 1, true)
        or msg:find("hwid", 1, true) and msg:find("does not match", 1, true)
end

local function validateKey(keyToTest, isAutoLogin)
    keyToTest = tostring(keyToTest or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if keyToTest == "" then return false, "Invalid Key" end

    local hwid = getHWID()

    for attempt = 1, 2 do
        if not sessionid then
            if not initKeyAuth() then
                if attempt == 2 then return false, "Init Failed" end
                task.wait(0.5)
                continue
            end
        end

        local url = string.format(
            "https://keyauth.win/api/1.2/?type=license&key=%s&hwid=%s&sessionid=%s&name=%s&ownerid=%s",
            urlEncode(keyToTest), urlEncode(hwid), urlEncode(sessionid), urlEncode(name), urlEncode(ownerid))

        local response = safeRequest({ Url = url, Method = "GET" })
        if response and response.StatusCode == 200 then
            local successDec, data = pcall(function() return HttpService:JSONDecode(response.Body) end)
            if successDec and data then
                if data.success then
                    if writefile then pcall(function() writefile(saveFileName, keyToTest) end) end
                    return true, "Success"
                end

                local msg = tostring(data.message or "Invalid Key")
                -- stale/invalid session: re-init once and retry
                if attempt == 1 and msg:lower():find("session", 1, true) then
                    sessionid = nil
                    continue
                end

                if isFatalKeyMessage(msg) and isfile and isfile(saveFileName) and delfile then
                    pcall(function() delfile(saveFileName) end)
                end
                return false, msg
            end
        end
        if attempt == 1 then task.wait(0.5) end
    end

    -- network/parse failure: never touch the saved key
    return false, "Connection Error"
end

----------------------------------------------------------------
-- UI HELPERS
----------------------------------------------------------------
local function tween(obj, props, time, style, dir)
    local t = TweenService:Create(obj, TweenInfo.new(time or 0.3, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), props)
    t:Play()
    return t
end

local function corner(parent, radius)
    local c = Instance.new("UICorner")
    c.CornerRadius = UDim.new(0, radius)
    c.Parent = parent
    return c
end

local function stroke(parent, color, transparency, thickness)
    local s = Instance.new("UIStroke")
    s.Color = color
    s.Transparency = transparency
    s.Thickness = thickness or 1
    s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    s.Parent = parent
    return s
end

local function label(parent, props)
    local l = Instance.new("TextLabel")
    l.BackgroundTransparency = 1
    l.BorderSizePixel = 0
    l.Font = Enum.Font.Gotham
    l.TextColor3 = Color3.fromRGB(255, 255, 255)
    l.TextSize = 14
    for k, v in pairs(props) do l[k] = v end
    l.Parent = parent
    return l
end

