    inputWrap.BorderSizePixel = 0
    inputWrap.Parent = main
    corner(inputWrap, 24)
    local inputStroke = stroke(inputWrap, Color3.fromRGB(255, 255, 255), 0.82, 1)

    local textBox = Instance.new("TextBox")
    textBox.Size = UDim2.new(1, -32, 1, 0)
    textBox.Position = UDim2.new(0, 16, 0, 0)
    textBox.BackgroundTransparency = 1
    textBox.BorderSizePixel = 0
    textBox.Font = Enum.Font.Gotham
    textBox.TextSize = 14
    textBox.Text = ""
    textBox.PlaceholderText = "License key"
    textBox.PlaceholderColor3 = Color3.fromRGB(190, 195, 210)
    textBox.TextColor3 = Color3.fromRGB(255, 255, 255)
    textBox.ClearTextOnFocus = false
    textBox.TextXAlignment = Enum.TextXAlignment.Left
    textBox.Parent = inputWrap

    textBox.Focused:Connect(function()
        playEmbedded("focus")
        tween(inputStroke, {Transparency = 0.2, Color = Color3.fromRGB(10, 132, 255)}, 0.25)
        tween(inputWrap, {BackgroundTransparency = 0.8}, 0.25)
    end)
    textBox.FocusLost:Connect(function()
        tween(inputStroke, {Transparency = 0.82, Color = Color3.fromRGB(255, 255, 255)}, 0.25)
        tween(inputWrap, {BackgroundTransparency = 0.88}, 0.25)
    end)

