    local submitBtn = Instance.new("TextButton")
    submitBtn.Size = UDim2.new(1, -40, 0, 48)
    submitBtn.Position = UDim2.new(0, 20, 0, 224)
    submitBtn.BackgroundColor3 = Color3.fromRGB(10, 132, 255)
    submitBtn.BackgroundTransparency = 0.05
    submitBtn.BorderSizePixel = 0
    submitBtn.AutoButtonColor = false
    submitBtn.Font = Enum.Font.GothamBold
    submitBtn.Text = "Verify Key"
    submitBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
    submitBtn.TextSize = 15
    submitBtn.Parent = main
    corner(submitBtn, 24)

    local btnGrad = Instance.new("UIGradient")
    btnGrad.Rotation = 90
    btnGrad.Color = ColorSequence.new(Color3.fromRGB(70, 165, 255), Color3.fromRGB(10, 110, 235))
    btnGrad.Parent = submitBtn
    stroke(submitBtn, Color3.fromRGB(255, 255, 255), 0.7, 1)

    submitBtn.MouseEnter:Connect(function()
        playEmbedded("hover")
        tween(submitBtn, {BackgroundTransparency = 0}, 0.2)
    end)
    submitBtn.MouseLeave:Connect(function()
        tween(submitBtn, {BackgroundTransparency = 0.05}, 0.2)
    end)

    -- status line
    local status = label(main, {
        Size = UDim2.new(1, -40, 0, 16),
        Position = UDim2.new(0, 20, 0, 280),
        Text = "",
        TextSize = 12,
        TextColor3 = Color3.fromRGB(255, 120, 120),
        TextXAlignment = Enum.TextXAlignment.Center,
    })

    -- divider + help
    local divider = Instance.new("Frame")
    divider.Size = UDim2.new(1, -40, 0, 1)
    divider.Position = UDim2.new(0, 20, 0, 304)
    divider.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    divider.BackgroundTransparency = 0.88
    divider.BorderSizePixel = 0
    divider.Parent = main

    label(main, {
        Size = UDim2.new(0, 190, 0, 34),
        Position = UDim2.new(0, 20, 0, 310),
        Text = "Need help or a key?\nContact us on Discord",
        TextSize = 11,
        TextColor3 = Color3.fromRGB(200, 205, 220),
        TextXAlignment = Enum.TextXAlignment.Left,
    })

    local discordBtn = Instance.new("TextButton")
    discordBtn.Size = UDim2.new(0, 112, 0, 30)
    discordBtn.Position = UDim2.new(1, -132, 0, 312)
    discordBtn.BackgroundColor3 = Color3.fromRGB(88, 101, 242)
    discordBtn.BackgroundTransparency = 0.25
    discordBtn.BorderSizePixel = 0
    discordBtn.AutoButtonColor = false
    discordBtn.Font = Enum.Font.GothamBold
    discordBtn.Text = DISCORD
    discordBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
    discordBtn.TextSize = 12
    discordBtn.Parent = main
    corner(discordBtn, 15)
    stroke(discordBtn, Color3.fromRGB(255, 255, 255), 0.75, 1)

    discordBtn.MouseEnter:Connect(function()
        playEmbedded("hover")
        tween(discordBtn, {BackgroundTransparency = 0.05}, 0.2)
    end)
    discordBtn.MouseLeave:Connect(function()
        tween(discordBtn, {BackgroundTransparency = 0.25}, 0.2)
    end)
    discordBtn.Activated:Connect(function()
        if setclipboard then
            playEmbedded("copy")
            pcall(function() setclipboard(DISCORD) end)
            discordBtn.Text = "Copied!"
            task.delay(1.5, function()
                if discordBtn.Parent then discordBtn.Text = DISCORD end
            end)
        else
            playEmbedded("click")
        end
    end)

    ----------------------------------------------------------------
    -- show / hide animations
    ----------------------------------------------------------------
    -- per-element fade (no CanvasGroup, so nothing gets dimmed)
    local fadeList = {}
    local function addFade(inst, prop)
        table.insert(fadeList, {inst = inst, prop = prop, orig = inst[prop]})
    end
    local function collectFade(inst)
        if inst:IsA("GuiObject") then
            addFade(inst, "BackgroundTransparency")
            if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
                addFade(inst, "TextTransparency")
            end
        elseif inst:IsA("UIStroke") then
            addFade(inst, "Transparency")
        end
    end
    collectFade(main)
    for _, d in ipairs(main:GetDescendants()) do collectFade(d) end
    for _, item in ipairs(fadeList) do item.inst[item.prop] = 1 end

    local function fade(visible, time)
        local last
        for _, item in ipairs(fadeList) do
            last = tween(item.inst, {[item.prop] = visible and item.orig or 1}, time)
        end
        return last
    end

    local closing = false
    local function closeUI(callback, silent)
        if closing then return end
        closing = true
        if not silent then playEmbedded("close") end
        tween(blur, {Size = 0}, 0.4)
        tween(scale, {Scale = 0.92}, 0.35)
        local t = fade(false, 0.35)
        if t then t.Completed:Wait() end
        screenGui:Destroy()
        blur:Destroy()
        if callback then callback() end
    end

    closeBtn.MouseEnter:Connect(function() playEmbedded("hover") end)
    closeBtn.Activated:Connect(function() closeUI() end)

    playEmbedded("open")
    fade(true, 0.55)
    tween(scale, {Scale = 1}, 0.6, Enum.EasingStyle.Back)

    ----------------------------------------------------------------
    -- dragging
    ----------------------------------------------------------------
    local dragging, dragInput, dragStart, startPos
    main.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            playEmbedded("drag")
            dragStart = input.Position
            startPos = main.Position
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    dragging = false
                end
            end)
        end
    end)
    main.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            dragInput = input
        end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if input == dragInput and dragging then
            local delta = input.Position - dragStart
            main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
        end
    end)

    ----------------------------------------------------------------
    -- verify logic
    ----------------------------------------------------------------
    local busy = false
    local function setStatus(text, color)
        status.Text = text
        status.TextColor3 = color
    end

    local function submit()
        if busy or closing then return end
        local enteredKey = textBox.Text
        if enteredKey == "" then
            playEmbedded("warn")
            setStatus("Please enter a key.", Color3.fromRGB(255, 120, 120))
            return
        end

        busy = true
        playEmbedded("enter", 0.7)
        submitBtn.Text = "Verifying..."
        setStatus("", Color3.fromRGB(255, 255, 255))
        tween(submitBtn, {BackgroundTransparency = 0.35}, 0.2)

        local success, msg = validateKey(enteredKey)
        if success then
            playEmbedded("success")
            submitBtn.Text = "Success"
            setStatus("Key accepted. Loading...", Color3.fromRGB(110, 230, 150))
            tween(submitBtn, {BackgroundColor3 = Color3.fromRGB(48, 209, 88), BackgroundTransparency = 0.05}, 0.3)
            btnGrad.Enabled = false
            task.wait(1)
            closeUI(function() executeMasterScript(enteredKey, getHWID()) end, true)
        else
            busy = false
            playEmbedded("error")
            submitBtn.Text = "Verify Key"
            textBox.Text = ""
            setStatus(tostring(msg), Color3.fromRGB(255, 120, 120))
            tween(submitBtn, {BackgroundTransparency = 0.05}, 0.2)
            -- little shake on failure
            local origin = inputWrap.Position
            for _, off in ipairs({8, -8, 5, -5, 0}) do
                tween(inputWrap, {Position = UDim2.new(origin.X.Scale, origin.X.Offset + off, origin.Y.Scale, origin.Y.Offset)}, 0.05, Enum.EasingStyle.Linear)
                task.wait(0.05)
            end
        end
    end

    submitBtn.Activated:Connect(submit)
    textBox.FocusLost:Connect(function(enterPressed)
        if enterPressed then submit() end
    end)
end

